  late MemoryExecutionEnv env;
  late _FakeCliIO io;

  setUp(() {
    env = MemoryExecutionEnv(cwd: '/work', shell: _FakeShell());
    io = _FakeCliIO();
  });

  tearDown(() => io.close());

  AgentCli cliFor(
