      final run = cli.run();
      io.sendLine('echo');
      await _waitFor(() => io.out.toString().contains('[approval] allow?'));
      io.sendLine('n');
      await _waitFor(() => io.out.toString().contains('denied-then'));
      expect(io.out.toString(), contains('The user denied'));
