    test('prompt-policy calls are denied with a reason', () async {
      io.isInteractive = false;
      final cli = cliFor([
        _toolTurn([bashCall('echo hi')]),
        _textTurn('adapted'),
      ], approvalMode: ApprovalMode.write);
      final run = cli.run();
      io.sendLine('run it');
      await _waitFor(
        () => io.out.toString().contains('adapted'),
