      config: AgentCliConfig(
        model: _model,
        apiKey: '[REDACTED:Sensitive Value]',
        env: env,
        sessionRoot: '/sessions',
        approvalMode: approvalMode,
        alwaysAllowTools: alwaysAllowTools,
        onApprovalChanged: onApprovalChanged,
      ),
      io: io,
