      io.isInteractive = false;
      final cli = cliFor([
        _toolTurn([bashCall('echo hi')]),
        _textTurn('adapted'),
      ], approvalMode: ApprovalMode.write);
      final run = cli.run();
      io.sendLine('run it');
      await _waitFor(
