      ]);
      final run = cli.run();
      io.sendLine('destroy');
      await _waitFor(() => io.out.toString().contains('refused'));
      final out = io.out.toString();
      expect(out, contains('✗ bash'));
      expect(out, contains('Critical pattern detected'));
      io.sendLine('/exit');
      await run;
    });
